 offline:()=>({msg:L('Offline — figures from 14:52. The forecast is cached; adding the plan to cart works and syncs later.','غير متصل — الأرقام من 14:52. التوقع محفوظ؛ إضافة الخطة للسلة تعمل وتُزامن لاحقاً.')}),
