 render:()=>{ const t=S.sub||'close', v=V('match');
  if (t==='open') { const c=COUNTS.open; return `<p class="small muted" style="margin-top:0">${L('Count the starting cash (float) note by note. Last close left','عُدّ النقد الافتتاحي فئة بفئة. آخر إغلاق ترك')} ${$(500)}.</p>${denomList(c)}<div class="card" style="margin-top:10px"><div class="recon"><span>${L('Counted float','الرصيد المعدود')}</span><b>${$(total(c))}</b><span>${L('Left at last close (Thu 12 Nov 23:40)','المتروك عند آخر إغلاق (الخميس 12 نوفمبر 23:40)')}</span><span>${$(500)}</span><span class="tot">${L('Difference','الفرق')}</span><span class="tot var-ok">${$(0)}</span></div></div>${notERP()}`; }
  const cnt=COUNTS[v], counted=total(cnt), exp=expected(), diff=counted-exp; const tol=TP.books.tolerance; const need=Math.abs(diff)>tol;
  const recon = `<div class="card"><div class="recon" role="status"><span>${L('Opening float','الرصيد الافتتاحي')}</span><span>${$(TODAYB.float)}</span><span>+ ${L('Cash sales','المبيعات النقدية')}</span><span>${$(TODAYB.cash)}</span><span>+ ${L('Cash in','إيداع نقدي')}</span><span>${$(TODAYB.cashIn)}</span><span>− ${L('Cash out','سحب نقدي')}</span><span>${$(TODAYB.cashOut)}</span><span>− ${L('Cash expenses','مصروفات نقدية')}</span><span>${$(TODAYB.expCash)}</span><span class="tot">${L('Expected in drawer','المتوقع في الدرج')}</span><span class="tot">${$(exp)}</span><span>${L('Counted','المعدود')}</span><b>${$(counted)}</b><span class="tot">${L('Variance','الفرق')}</span><span class="tot ${diff<0?'var-bad':'var-ok'}">${diff===0?$(0):`${diff<0?L('Short','عجز'):L('Over','زيادة')} ${$(Math.abs(diff))}`}</span></div>
   ${diff===0?`<div class="small" style="margin-top:6px;color:var(--ok)">${ic('check')} ${L('Drawer matches','الدرج مطابق')}</div>`:need?`<div class="banner warn" style="margin-bottom:0">${ic('alert')}<div class="grow small"><b>${L('Variance above','فرق أكبر من')} ${$(tol)}</b>${L('Recount, or add a reason before closing. It is saved with the shift report.','أعد العدّ أو أضف سبباً قبل الإغلاق. يُحفظ مع تقرير الوردية.')}</div></div>`:`<div class="small muted" style="margin-top:6px">${L('Within the','ضمن')} ${$(tol)} ${L('tolerance — no reason needed','المسموح — لا حاجة لسبب')}</div>`}</div>`;
  if (t==='summary') return `${MF.badge('sample')}<div class="card" style="margin-top:8px"><div class="row between wrap"><b>${L('Shift report','تقرير الوردية')} · ${MF.ltr('SH-1113-01')}</b><span class="small muted" dir="ltr">11:30 – 15:10</span></div><dl class="dl" style="margin-top:8px"><dt>${L('Opened by','فتحها')}</dt><dd>${L('Hala A.','هالة ع.')}</dd><dt>${L('Closed by','أغلقها')}</dt><dd>${L('Omar S.','عمر س.')}</dd><dt>${L('Sales (all)','المبيعات (الكل)')}</dt><dd>${$(TODAYB.cash+TODAYB.card+TODAYB.apps)}</dd><dt>${L('Card / mada','بطاقة / مدى')}</dt><dd>${$(TODAYB.card)}</dd><dt>${L('Delivery apps','تطبيقات التوصيل')}</dt><dd>${$(TODAYB.apps)}</dd></dl></div><div style="margin-top:10px">${recon}</div><p class="small muted">${L('A shift report is for your records. It is not a tax invoice and does not replace your POS receipts.','تقرير الوردية لسجلاتك. ليس فاتورة ضريبية ولا يغني عن إيصالات نقطة البيع.')}</p>`;
  return `${denomList(cnt)}<div style="margin-top:10px">${recon}</div>
   <label class="field" style="margin-top:10px"><span>${L('Reason for variance','سبب الفرق')}${need?' *':` (${L('optional','اختياري')})`}</span><textarea class="inp ${need?'bad':''}" dir="auto" rows="2">${need?'':''}</textarea>${need?`<em class="err">${L('Add a reason (e.g. change given wrongly) or recount.','أضف سبباً (مثال: خطأ في إرجاع الباقي) أو أعد العدّ.')}</em>`:`<em>${L('Saved in the shift report.','يُحفظ في تقرير الوردية.')}</em>`}</label>
   <label class="field"><span>${L('Cash left in drawer for next shift','النقد المتروك للوردية التالية')}</span><input class="inp ltr num" inputmode="decimal" value="500.00"><em>${L('The rest goes to the safe or bank deposit.','الباقي يذهب للخزنة أو الإيداع البنكي.')}</em></label>`; },
 primary:()=>{ const t=S.sub||'close'; if (t==='summary') return {label:L('Share PDF','شارك PDF'),icon:'share',act:`toast:${L('Shift report PDF ready (sample)','تقرير الوردية PDF جاهز (تجريبي)')}`,fab:false}; if (t==='open') return {label:L('Open shift with','افتح الوردية بـ')+' 500.00',icon:'check',act:`toast:${L('Shift opened','فُتحت الوردية')}`,fab:false};
  const need = Math.abs(total(COUNTS[V('match')])-expected())>TP.books.tolerance; return {label:need?L('Add reason to close','أضف السبب للإغلاق'):L('Close shift','أغلق الوردية'),icon:'lock',act:need?'noop':'ov:close',disabled:need,fab:false,sum:`<b>${$(total(COUNTS[V('match')]))}</b>${L('counted','معدود')}`}; },
