 empty:()=>({icon:'cash',t:L('No open shift','لا وردية مفتوحة'),b:L('Open a shift to start counting.','افتح وردية لبدء العدّ.'),cta:L('Open shift','افتح وردية'),go:'h.shift?sub=open'}),
 error:()=>({t:L("Couldn't save the count","تعذّر حفظ العدّ"),b:L('Your count is kept on this device. Try again.','عدّك محفوظ على الجهاز. حاول مجدداً.'),code:'SHIFT'}),
