  if (v==='subscribed') return `<div class="card"><div class="row between wrap"><b>${L('Books · Premium add-on','الدفاتر · إضافة المميّزة')}</b><span class="tag ok">${L('Active','نشط')}</span></div><dl class="dl" style="margin-top:8px"><dt>${L('Price','السعر')}</dt><dd>${MF.badge2('price')}</dd><dt>${L('Billing','الفوترة')}</dt><dd>${L('Monthly · on your MENAFoods statement','شهرياً · على كشف حسابك لدى ميناء فودز')}</dd><dt>${L('Renews','التجديد')}</dt><dd>${MF.dateG('2026-12-05')}</dd><dt>${L('Users','المستخدمون')}</dt><dd>${L('Owner + 2 cashiers','المالك + كاشيران')}</dd></dl></div><div class="row wrap" style="margin-top:10px"><button class="btn" data-act="toast:${L('Cashier invite sent on WhatsApp (prototype)','أُرسلت دعوة الكاشير عبر واتساب (نموذج)')}">${ic('users')} ${L('Invite cashier','ادعُ كاشيراً')}</button><button class="btn danger" data-act="ov:cancel">${L('Cancel Books','إلغاء الدفاتر')}</button></div><p class="small muted">${L('If your tier changes to Normal, Books stays active until the end of the paid month, then becomes read-only for 90 days.','إذا تغيّرت فئتك إلى عادي تبقى الدفاتر فعالة حتى نهاية الشهر المدفوع ثم تصبح للقراءة فقط 90 يوماً.')}</p>`;
