 error:()=>({t:L("Loyalty rules didn't load","لم تُحمّل قواعد الولاء"),b:L('Customers keep earning on current rules.','يستمر العملاء بالكسب وفق القواعد الحالية.'),code:'LOY'}),
 offline:()=>({msg:L('Offline — view only.','غير متصل — للعرض فقط.'),q:false}),
 loadingMsg:()=>L('Loading loyalty rules…','جارٍ تحميل قواعد الولاء…'),
